import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";

import * as Progress from "../../ui/progress";

// MODEL

export const Model = S.Struct({
  value: S.Number,
});

export type Model = typeof Model.Type;

// MESSAGE

export const Message = m("Message");

export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ value: 20 }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      Message: () => [model, []],
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("flex flex-col items-start gap-4")],
    [
      Progress.view<Message>({
        value: model.value,
        label: "Export data",
        id: "export-data-progress-label",
      }),
    ]
  );
});

import { Runtime } from "foldkit";

import { Model, init, update, view } from "./main";

const program = Runtime.makeProgram({
  Model,
  init,
  update,
  view: (model) => ({
    title: "Progress Basic",
    body: view(model),
  }),
  container: document.querySelector("#root"),
});

Runtime.run(program);

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as ProgressBasicExample from "./main";

describe("Progress Basic example", () => {
  test("matches the Base UI progress hero example content", () => {
    Scene.scene(
      { update: ProgressBasicExample.update, view: ProgressBasicExample.view },
      Scene.with(ProgressBasicExample.init()[0]),
      Scene.expect(Scene.text("Export data")).toExist(),
      Scene.expect(Scene.text("20%")).toExist(),
      Scene.expect(
        Scene.role("progressbar", { name: "Export data" })
      ).toHaveAttr("aria-valuenow", "20"),
      Scene.expect(
        Scene.role("progressbar", { name: "Export data" })
      ).toHaveAttr("aria-valuemin", "0"),
      Scene.expect(
        Scene.role("progressbar", { name: "Export data" })
      ).toHaveAttr("aria-valuemax", "100"),
      Scene.expect(
        Scene.role("progressbar", { name: "Export data" })
      ).toHaveAttr("aria-valuetext", "20%"),
      Scene.expect(
        Scene.role("progressbar", { name: "Export data" })
      ).toHaveAttr("data-progressing", ""),
      Scene.expect(Scene.text("Export data")).not.toHaveHandler("click"),
      Scene.expect(Scene.text("20%")).not.toHaveHandler("click")
    );
  });
});
